using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CareerTests
{
    static WorldSession New(bool recruits=true,bool dismissed=false)=>new(Career.Create(recruits:recruits,dismissAfterReport:dismissed));
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);var before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static EntityId Apply(WorldSession s,string id="request:career/apply"){var input=new CareerInput(new(id),CareerAction.Apply);Assert.Equal(ResultCode.Accepted,s.DecideCareer(input,s.PlayerControl,s.Revision).Code);return input.Id;}
    static string Notice(WorldSession s,CareerEventKind kind,EntityId? id=null)=>s.DiagnosticSnapshot().Career!.Events.Last(e=>e.Kind==kind&&(id==null||e.Case==id)).Message;
    static long Due(WorldSession s,string message)=>MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,message).DueAt;
    static void Open(WorldSession s,string message)=>Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(message),s.Revision).Code);
    static void Respond(WorldSession s,EntityId id,CareerAction action,string request="request:career/response")=>Assert.Equal(ResultCode.Accepted,s.DecideCareer(new(new(request),action,id),s.PlayerControl,s.Revision).Code);
    static EntityId Join(WorldSession s,string label="first"){var id=Apply(s,"request:career/apply/"+label);At(s,Due(s,s.DiagnosticSnapshot().Career!.Requests.Last().Message)+1);Open(s,Notice(s,CareerEventKind.Offered,id));Respond(s,id,CareerAction.Accept,"request:career/accept/"+label);At(s,Due(s,s.DiagnosticSnapshot().Career!.Requests.Last().Message)+1);Open(s,Notice(s,CareerEventKind.Joined,id));return id;}
    static void Work(WorldSession s){var card=RegionalWork.Inbox(s).Last(c=>c.CanOpen);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,card.Message,s.Revision).Code);var pending=RegionalWork.Inbox(s).LastOrDefault(c=>c.CanDecide);if(pending!=null)Assert.Equal(ResultCode.Accepted,s.Assent(pending.Task!.Value,s.PlayerControl,true,s.Revision).Code);At(s,s.Seconds+5);}
    [Fact] public void InitialRoninIsTheSameIndependentPersonWithoutMilitaryRights(){var w=Career.Create();Assert.Equal(PersonalStart.Person,w.PlayerControl);Assert.DoesNotContain(w.Memberships,m=>m.Subject==w.PlayerControl);Assert.DoesNotContain(w.ServiceBonds,m=>m.Subject==w.PlayerControl);Assert.DoesNotContain(w.Units,u=>u.Commander==w.PlayerControl);Assert.True(Career.View(new(w),w.PlayerControl).CanApply);}
    [Fact] public void MutualAssentIsEffectiveBeforeTheSealedConfirmationIsKnown(){var s=New();var id=Apply(s);At(s,2);Assert.Null(s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id.Value==Notice(s,CareerEventKind.Offered)).KnownBody);Assert.False(Career.View(s,s.PlayerControl).Cases.Single().CanAccept);Open(s,Notice(s,CareerEventKind.Offered));Respond(s,id,CareerAction.Accept);At(s,3);var w=s.DiagnosticSnapshot();Assert.Single(w.Memberships,m=>m.Subject==s.PlayerControl);Assert.Single(w.ServiceBonds,m=>m.Subject==s.PlayerControl);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);At(s,4);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);Open(s,Notice(s,CareerEventKind.Joined));Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);Assert.DoesNotContain(s.DiagnosticSnapshot().Units,u=>u.Commander==s.PlayerControl);}
    [Fact] public void LiteralPreviousRoninInitialKeepsItsDefinition(){var w=ContractJson.Read<ContractWorld>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","ronin-9959278-initial.json")));Assert.Null(w.Career);Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(PersonalStart.Create("検証仕官前")));}
    [Fact] public void ReleaseEndsBothPeriodsOnlyAfterPrincipalReceivesOwnWorkReport(){var s=New();var id=Join(s);Respond(s,id,CareerAction.RequestRelease,"request:career/release");At(s,5);Assert.Contains(s.DiagnosticSnapshot().Career!.Events,e=>e.Kind==CareerEventKind.ReleaseWaiting);Assert.True(Career.ActiveAt(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds));Work(s);var w=s.DiagnosticSnapshot();var ended=w.Career!.Events.Single(e=>e.Kind==CareerEventKind.Released);Assert.False(Career.ActiveAt(w,RetainerStart.Lord,s.Seconds));Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);At(s,Due(s,ended.Message));Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);Open(s,ended.Message);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);Assert.Equal(w.WorldId,s.DiagnosticSnapshot().WorldId);Assert.Equal(w.PlayerControl,s.PlayerControl);}
    [Fact] public void FixtureDismissalUsesReceivedReportAndDoesNotEndTheLife(){var s=New(dismissed:true);var id=Join(s);Work(s);var w=s.DiagnosticSnapshot();var end=w.Career!.Events.Single(e=>e.Kind==CareerEventKind.Dismissed);Assert.True(MessageFlow.Knows(w.Messaging,end.Related,RetainerStart.Lord.Value));Assert.False(Career.ActiveAt(w,RetainerStart.Lord,s.Seconds));Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);At(s,Due(s,end.Message));Open(s,end.Message);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);Assert.Equal(LifeState.Adult,s.DiagnosticSnapshot().Characters.Single(c=>c.Id==s.PlayerControl).Life);Assert.DoesNotContain(s.DiagnosticSnapshot().Units,u=>u.Commander==s.PlayerControl);}
    [Fact] public void RefusalIsPrivateUntilItsSealedReplyIsOpened(){var a=New();var b=New(false);Apply(a);Apply(b);At(a,2);At(b,2);Assert.Equal(Career.View(a,a.PlayerControl).Role,Career.View(b,b.PlayerControl).Role);Assert.Equal(Career.View(a,a.PlayerControl).Cases.Single().Status,Career.View(b,b.PlayerControl).Cases.Single().Status);Assert.DoesNotContain(b.DiagnosticSnapshot().Memberships,m=>m.Subject==b.PlayerControl);Open(b,Notice(b,CareerEventKind.Refused));Assert.Contains("不承諾",Career.View(b,b.PlayerControl).Cases.Single().Status);Assert.True(Career.View(b,b.PlayerControl).CanApply);}
    [Fact] public void LateOpeningOfOldAgreementCannotUndoKnownTermination(){var s=New(dismissed:true);var id=Apply(s);At(s,2);Open(s,Notice(s,CareerEventKind.Offered));Respond(s,id,CareerAction.Accept);At(s,4);Work(s);var end=Notice(s,CareerEventKind.Dismissed);At(s,Due(s,end));Open(s,end);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);Open(s,Notice(s,CareerEventKind.Joined));Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);}
    [Fact] public void OldBindingTaskKeepsItsIssuanceKindAfterRelease(){var s=New(dismissed:true);Join(s);Work(s);var w=s.DiagnosticSnapshot();var r=w.Requests.Single(r=>r.Intent.Actor==RetainerStart.Lord&&r.Intent.Action==ActionKind.Inspect);Assert.Equal(TaskKind.BindingOrder,r.Intent.Kind);Assert.Equal(TaskKind.VoluntaryRequest,RegionalWork.Kind(w,RetainerStart.Lord));ContractValidation.Validate(w);}
    [Theory][InlineData(0)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void SaveAndRestorePreservesApplicationAssentAndKnownRole(int at){var s=New();var id=Apply(s);if(at>=2){At(s,2);Open(s,Notice(s,CareerEventKind.Offered));Respond(s,id,CareerAction.Accept);}At(s,at);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"career-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));At(s,10);At(host.Current,10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(Career.View(s,s.PlayerControl).Role,Career.View(host.Current,host.Current.PlayerControl).Role);}

    [Fact] public void UnopenedOfferCannotBeAcceptedAndOtherActorsCannotDecide(){var s=New();var id=Apply(s);At(s,2);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideCareer(new(new("request:hidden-accept"),CareerAction.Accept,id),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.DecideCareer(new(new("request:other-actor"),CareerAction.Accept,id),RetainerStart.Lord,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact] public void DuplicateBusinessIdIsImmutableAndDoesNotResend(){var s=New();var id=Apply(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideCareer(new(id,CareerAction.Apply),s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideCareer(new(id,CareerAction.Inquire,id),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact] public void SameIdCannotBeReusedAcrossCareerAndTravel(){var s=New();var id=Apply(s,"request:shared-career-travel");var i=TravelWorld.Move(s.DiagnosticSnapshot(),id.Value,"kofu");Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(i,s.Revision).Code);var other=New();Assert.Equal(ResultCode.Accepted,other.Submit(TravelWorld.Move(other.DiagnosticSnapshot(),"request:shared-career-travel","kofu"),other.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,other.DecideCareer(new(id,CareerAction.Apply),other.PlayerControl,other.Revision).Code);}
    [Fact] public void DeclineCreatesNoServiceAndCanApplyAgainAfterReceipt(){var s=New();var id=Apply(s);At(s,2);Open(s,Notice(s,CareerEventKind.Offered));Respond(s,id,CareerAction.Decline);At(s,4);Assert.DoesNotContain(s.DiagnosticSnapshot().Memberships,m=>m.Subject==s.PlayerControl);Assert.False(Career.View(s,s.PlayerControl).CanApply);Open(s,Notice(s,CareerEventKind.Declined));Assert.True(Career.View(s,s.PlayerControl).CanApply);}
    [Fact] public void DeadlineIsAcceptanceReceiptNotTheClickTime(){var s=New();var id=Apply(s);At(s,2);Open(s,Notice(s,CareerEventKind.Offered));At(s,120);Respond(s,id,CareerAction.Accept);At(s,122);Assert.DoesNotContain(s.DiagnosticSnapshot().Career!.Events,e=>e.Kind==CareerEventKind.Joined);Assert.Equal(AttemptStatus.Rejected,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,s.DiagnosticSnapshot().Career!.Requests.Last().Message).Status);Open(s,Notice(s,CareerEventKind.Expired));Assert.True(Career.View(s,s.PlayerControl).CanApply);}
    [Fact] public void LostAcceptanceCannotCreateRightsAtThePrincipal(){var s=New();var id=Apply(s);At(s,2);Open(s,Notice(s,CareerEventKind.Offered));Respond(s,id,CareerAction.Accept);string answer=s.DiagnosticSnapshot().Career!.Requests.Last().Message;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,answer));At(s,122);Assert.DoesNotContain(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==s.PlayerControl);Assert.DoesNotContain(s.DiagnosticSnapshot().Career!.Events,e=>e.Kind==CareerEventKind.Joined);}
    [Fact] public void LostConfirmationIsRecoveredAsInformationByNewStatusLetter(){var s=New();var id=Apply(s);At(s,2);Open(s,Notice(s,CareerEventKind.Offered));Respond(s,id,CareerAction.Accept);At(s,3);string original=Notice(s,CareerEventKind.Joined);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,4);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);Respond(s,id,CareerAction.Inquire,"request:career/status");At(s,6);Open(s,Notice(s,CareerEventKind.StatusSent));Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,original,s.PlayerControl.Value));Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==original);}
    [Fact] public void LostEndNoticeCanBeQuotedWithoutForgingItsReceipt(){var s=New(dismissed:true);var id=Join(s);Work(s);string original=Notice(s,CareerEventKind.Dismissed);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,Due(s,original));Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);Respond(s,id,CareerAction.Inquire,"request:career/end-status");At(s,s.Seconds+2);Open(s,Notice(s,CareerEventKind.StatusSent));Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,original,s.PlayerControl.Value));}
    [Fact] public void RejoiningKeepsSeparatePeriodsAndOldNoticeCannotUndoNewService(){var s=New();var first=Join(s);Work(s);Respond(s,first,CareerAction.RequestRelease,"request:career/release");At(s,s.Seconds+1);string original=Notice(s,CareerEventKind.Released);At(s,Due(s,original));Respond(s,first,CareerAction.Inquire,"request:career/end-status");At(s,s.Seconds+2);Open(s,Notice(s,CareerEventKind.StatusSent));var second=Join(s,"second");Open(s,original);var w=s.DiagnosticSnapshot();Assert.StartsWith("織田家所属",Career.View(s,s.PlayerControl).Role);Assert.Equal(2,w.Memberships.Count(m=>m.Subject==s.PlayerControl));Assert.Equal(2,w.ServiceBonds.Count(m=>m.Subject==s.PlayerControl));Assert.Equal(w.PlayerControl,s.PlayerControl);Assert.NotEqual(first,second);ContractValidation.Validate(w);}
    [Fact] public void AfterDismissalTheSamePersonCanTravelAndTakeVoluntaryWork(){var s=New(dismissed:true);Join(s);Work(s);string end=Notice(s,CareerEventKind.Dismissed);At(s,Due(s,end));Open(s,end);var identity=s.PlayerControl;var world=s.DiagnosticSnapshot().WorldId;Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:career/after-exit-travel","kofu"),s.Revision).Code);At(s,s.Seconds+2);long arrival=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt;At(s,arrival+1);Assert.Equal(identity,s.PlayerControl);Assert.Equal(world,s.DiagnosticSnapshot().WorldId);Assert.StartsWith("浪人",Career.View(s,s.PlayerControl).Role);var local=s.DiagnosticSnapshot().Tasks.Last(t=>t.Action==ActionKind.Inspect);Assert.Equal(new EntityId("person:shingen"),local.Issuer);Assert.Equal(TaskKind.VoluntaryRequest,local.Kind);}
    [Theory][InlineData("membership")][InlineData("opening")][InlineData("notice")][InlineData("policy")][InlineData("effect-time")]
    public void ForgedCareerCannotLoad(string kind){var s=New(dismissed:true);Join(s);Work(s);var w=s.DiagnosticSnapshot();if(kind=="membership")w.Memberships=w.Memberships.Select(m=>m.Subject==w.PlayerControl?m with{From=0}:m).ToArray();if(kind=="opening")w.Career=w.Career! with{Openings=w.Career.Openings.Select(o=>o with{Revision=w.CommitSequence+1}).ToArray()};if(kind=="notice"){var id=Notice(s,CareerEventKind.Joined);w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==id?m with{Body="{}"}:m).ToArray();}if(kind=="policy"){w.Career=w.Career! with{Terms=w.Career.Terms with{DismissAfterReport=false}};w.Definitions=w.Definitions with{Version=RegionalBattle.Version(w)};}if(kind=="effect-time"){var e=w.Career!.Events.Single(e=>e.Kind==CareerEventKind.Joined);w.Career=w.Career with{Events=w.Career.Events.Select(x=>x.Id==e.Id?x with{At=0}:x).ToArray()};}Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}

    [Theory][InlineData(false,false)][InlineData(true,false)][InlineData(true,true)]
    public void SaveAfterEndPreservesUnknownNoticeOrOngoingRoadPosition(bool dismissed,bool travel){var s=New(dismissed:dismissed);var id=Join(s);Work(s);if(!dismissed){Respond(s,id,CareerAction.RequestRelease,"request:career/release");At(s,s.Seconds+1);}string end=Notice(s,dismissed?CareerEventKind.Dismissed:CareerEventKind.Released);if(travel){At(s,Due(s,end));Open(s,end);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:career/road-after-end","kofu"),s.Revision).Code);At(s,s.Seconds+2);}s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"career-end-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New(dismissed:dismissed));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));At(s,s.Seconds+10);At(host.Current,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.GetBranchView(s.PlayerControl)),ContractJson.Write(host.Current.GetBranchView(host.Current.PlayerControl)));}

    [Fact] public void LegacyNpcDecisionInputRetainsItsExactJsonShape(){var bytes=System.Text.Encoding.UTF8.GetBytes("{\"LocalWitness\":true,\"InspectionPermit\":true,\"OwnTasks\":[],\"LastReportKnown\":true,\"KnownResult\":null,\"ReadyAt\":\"0\",\"CooldownElapsed\":true}");var input=ContractJson.Read<NpcWorkInputs>(bytes);Assert.False(input.DialoguePending);Assert.Equal(bytes,ContractJson.Write(input));}

}
